class Solution {public:int solve(vector<vector<int>> grid){int m=grid.size(),n=m?grid[0].size():0;vector<vector<bool>>seen(m,vector<bool>(n));set<vector<pair<int,int>>>shapes;int dr[]={-1,1,0,0},dc[]={0,0,-1,1};for(int r=0;r<m;r++)for(int c=0;c<n;c++)if(grid[r][c]&&!seen[r][c]){vector<pair<int,int>>q{{r,c}},points;seen[r][c]=true;for(int i=0;i<(int)q.size();i++){auto [x,y]=q[i];points.push_back({x-r,y-c});for(int k=0;k<4;k++){int a=x+dr[k],b=y+dc[k];if(a>=0&&a<m&&b>=0&&b<n&&grid[a][b]&&!seen[a][b]){seen[a][b]=true;q.push_back({a,b});}}}sort(points.begin(),points.end());shapes.insert(points);}return shapes.size();}};